// --- RENDERIZAÇÃO DOS CARDS (GRID) ---
function renderizarItensTinetti() {
const container = document.getElementById("tinettiForm");
container.innerHTML = "";

let currentSection = "";

ITENS_TINETTI.forEach((item) => {
// Criar divisória se mudar de seção (Equilíbrio -> Marcha)
if (item.type !== currentSection) {
const secTitle = document.createElement("div");
secTitle.className = "col-span-full text-[15px] font-bold text-navy border-b-2 border-slate-100 pb-1 mt-4 mb-2 uppercase tracking-wide";
secTitle.textContent = `Оцінка ${item.type}`;
container.appendChild(secTitle);
currentSection = item.type;
}

let optsHtml = "";
item.opts.forEach((op) => {
optsHtml += `<option value="${op.val}" ${op.val === "" ? "disabled selected" : ""}>${op.text}</option>`;
});

const div = document.createElement("div");
div.className = "item-card";
div.id = `card_${item.id}`;
div.innerHTML = `
<div class="flex items-center justify-between mb-2">
<label for="${item.id}" class="text-[13px] font-bold text-slate-800">${item.label}</label>
<span id="badge_${item.id}" class="item-badge">--/${item.max}</span>
</div>
<select id="${item.id}" class="item-select">${optsHtml}</select>
<div class="mini-bar-wrap">
<div id="bar_${item.id}" class="mini-bar-fill" style="width: 0%;"></div>
</div>
`;
container.appendChild(div);

const el = document.getElementById(item.id);
el.addEventListener("change", () => {
document.getElementById(`card_${item.id}`).classList.remove("error");
document.getElementById("msgValidacaoErro").style.display = "none";
atualizarCardIndividual(item.id, item.max);
});

el.addEventListener('change', startTimer, {once: true});
el.addEventListener("wheel", function(e) { e.preventDefault(); this.blur(); });
});
}

// --- ATUALIZAR STATUS DE UM CARD ESPECÍFICO ---
function atualizarCardIndividual(id, max) {
const select = document.getElementById(id);
const valStr = select.value;
if (valStr === "") return;
const val = parseInt(valStr);
// Barra sempre visível: mínimo 8% para mostrar a cor
const pct = Math.max((val / max) * 100, 8);

const badge = document.getElementById(`badge_${id}`);
const bar = document.getElementById(`bar_${id}`);

badge.textContent = `${val}/${max}`;
bar.style.width = `${pct}%`;

// Cores baseadas na pontuação (Tinetti: quanto maior, melhor)
let cor = "#e11d48"; // 0 pts = Vermelho (alto risco)
if (val === max) cor = "#16a34a"; // Máximo = Verde (baixo risco)
else if (val > 0 && val < max) cor = "#eab308"; // Intermediário = Amarelo

bar.style.backgroundColor = cor;

// Badge também muda de cor conforme escore
badge.style.backgroundColor = cor === "transparent" ? "" : `${cor}15`;
badge.style.color = cor === "transparent" ? "" : cor;
badge.style.borderColor = cor === "transparent" ? "" : `${cor}30`;
atualizarBarraGlobal();
}

// --- BARRA FLUTUANTE GLOBAL E CONTADOR ---
function atualizarBarraGlobal() {
let preenchidos = 0;
ITENS_TINETTI.forEach((i) => {
if (document.getElementById(i.id).value !== "") preenchidos++;
});

const pctGlobal = (preenchidos / 18) * 100;
document.getElementById("progress-bar-global").style.width = `${pctGlobal}%`;
document.getElementById("contadorPreenchidos").textContent = `${preenchidos}/18`;
}

// --- LÓGICA DADOS DO PACIENTE (TOGGLE) ---
