const body = document.getElementById("dadosBody");
const chevron = document.getElementById("dadosChevron");
const subtitle = document.getElementById("dadosSubtitle");

if (body.classList.contains("open")) {
body.classList.remove("open");
chevron.style.transform = "rotate(0deg)";
subtitle.textContent = "Заповнити для медичної карти / висновку PDF";
this.style.background = "white";
} else {
body.classList.add("open");
chevron.style.transform = "rotate(180deg)";
subtitle.textContent = "Приховати панель";
this.style.background = "#EFF6FF";
}
});
document.getElementById("pacData").value = new Date().toISOString().split("T")[0];

// --- CÁLCULO E RESULTADO ---
const resultadoSection = document.getElementById("resultado-section");

function calcular() {
let incompleto = false;
let somaTotal = 0;
let dominiosValores = [];
let diagnosticosKeywords = ["queda", "equilíbrio", "mobilidade", "físico", "risco"];
let primeiroErro = null;

ITENS_TINETTI.forEach((item) => {
const selectVal = document.getElementById(item.id).value;
if (selectVal === "") {
incompleto = true;
document.getElementById(`card_${item.id}`).classList.add("error");
if(!primeiroErro) primeiroErro = document.getElementById(`card_${item.id}`);
dominiosValores.push({ nome: item.label, obtido: 0, max: item.max });
} else {
document.getElementById(`card_${item.id}`).classList.remove("error");
const val = parseInt(selectVal);
somaTotal += val;
dominiosValores.push({ nome: item.label, obtido: val, max: item.max });

// Alimentando palavras-chave para o NANDA se a pontuação for perigosa
if (val < item.max) {
if (item.type === "Marcha") diagnosticosKeywords.push("marcha", "deambulação");
if (item.type === "Equilíbrio") diagnosticosKeywords.push("fraqueza", "autocuidado", "posicionamento");
}
}
});

if (incompleto) {
const msgErro = document.getElementById("msgValidacaoErro");
msgErro.style.display = "block";
if (primeiroErro) {
primeiroErro.scrollIntoView({ behavior: 'smooth', block: 'center' });
}
return;
}

document.getElementById("msgValidacaoErro").style.display = "none";
clearInterval(timerInterval);

// Determinar Classificação Tinetti (Max 28)
// Padrão clássico: <=18 Alto Risco, 19-23 Moderado, >=24 Baixo Risco
let classe = "", bgPill = "", recomendacao = "";
if (somaTotal <= 18) {
classe = "Високий ризик падіння"; bgPill = "#e11d48"; // Vermelho
recomendacao = "Вказує на серйозний ризик падінь. Обов’язкове негайне впровадження протоколу запобігання падінням (поручні, освітлення, доступний дзвінок), допомога з мобільністю та супровід.";
} else if (somaTotal <= 23) {
classe = "Помірний ризик"; bgPill = "#eab308"; // Amarelo
recomendacao = "Вказує на помірний ризик. Рекомендується адаптація навколишнього середовища, використання допоміжних засобів для ходьби, якщо це показано, та нагляд під час ходьби.";
} else {
classe = "Низький ризик"; bgPill = "#16a34a"; // Verde
recomendacao = "Вказує на низький ризик падінь. Пацієнт має добру рівновагу та функціональну ходу. Підтримуйте стандартні профілактичні заходи та заохочуйте фізичну активність, спрямовану на зміцнення та рівновагу.";
}

// Exibir no Hero Card
document.getElementById("scoreValor").textContent = somaTotal;
const pill = document.getElementById("statusPill");
pill.textContent = classe;
pill.style.backgroundColor = bgPill;

// Destacar card correspondente no Sidebar
const scpIds = ["scp-baixo", "scp-moderado", "scp-alto"];
scpIds.forEach(id => {
const el = document.getElementById(id);
if (el) {
el.style.transform = "scale(1)";
el.style.boxShadow = "";
el.classList.remove("scp-highlight");
}
});

let scpAlvo = null;
if (somaTotal <= 18) scpAlvo = document.getElementById("scp-alto");
else if (somaTotal <= 23) scpAlvo = document.getElementById("scp-moderado");
else scpAlvo = document.getElementById("scp-baixo");

if (scpAlvo) {
scpAlvo.style.transform = "scale(1.03)";
scpAlvo.style.boxShadow = "0 8px 25px rgba(0,0,0,0.25)";
scpAlvo.classList.add("scp-highlight");
}

document.getElementById("resultadoMensagem").innerHTML = `Пацієнт отримав <strong>${somaTotal} балів</strong> з 28 можливих.<br><br><strong>Рекомендації:</strong> ${recomendacao}`;

// Gerar Tabela de Detalhamento
const tbody = document.getElementById("tabelaDominios");
tbody.innerHTML = "";
dominiosValores.forEach((dom) => {
const pct = Math.round((dom.obtido / dom.max) * 100);

let cor = "#e11d48"; // Vermelho (0)
if (dom.obtido === dom.max) cor = "#16a34a"; // Verde (Máximo)
else if (dom.obtido > 0 && dom.obtido < dom.max) cor = "#eab308"; // Amarelo (Intermediário)

const tr = document.createElement("tr");
tr.innerHTML = `
<td class="font-bold text-slate-700">${dom.nome}</td>
<td class="text-center font-black" style="color: ${cor}">${dom.obtido}</td>
<td class="text-center text-slate-400">${dom.max}</td>
<td>
<div class="flex items-center gap-3">
<div class="flex-1 h-[6px] bg-slate-200 rounded-full overflow-hidden">
<div style="width: ${pct}%; background-color: ${cor};" class="h-full rounded-full"></div>
</div>
<span class="text-[11px] font-bold" style="color: ${cor}">${pct}%</span>
</div>
</td>
`;
tbody.appendChild(tr);
});
document.getElementById("totalObtidoTd").textContent = somaTotal;
document.getElementById("totalObtidoTd").style.color = bgPill;

// Mostrar Seção
resultadoSection.classList.add("visible");
resultadoSection.style.display = "block";
setTimeout(() => {
resultadoSection.scrollIntoView({ behavior: "smooth", block: "start" });
}, 100);

// Chamar NANDA
chamarNanda(diagnosticosKeywords);

window.__calcData = { soma: somaTotal, classe, dominios: dominiosValores };
}

async function chamarNanda(keywords) {
const lista = document.getElementById("lista-nanda");
lista.innerHTML = '<li class="text-sm text-slate-500 text-center py-4"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="fa-spin mr-2 inline-block" fill="currentColor" width="1em" height="1em" aria-hidden="true"><path d="M304 48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zm0 416a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM48 304a48 48 0 1 0 0-96 48 48 0 1 0 0 96zm464-48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM142.9 437A48 48 0 1 0 75 369.1 48 48 0 1 0 142.9 437zm0-294.2A48 48 0 1 0 75 75a48 48 0 1 0 67.9 67.9zM369.1 437A48 48 0 1 0 437 369.1 48 48 0 1 0 369.1 437z"/></svg> Підключення до бази даних NANDA-I...</li>';

try {
const response = await fetch("/banco_nanda.json");
if (!response.ok) throw new Error("Помилка отримання");
const banco = await response.json();

const pontuados = banco
.map((diag) => {
let matchScore = 0;
const texto = (diag.diagnostico + " " + diag.definicao).toLowerCase();
keywords.forEach((kw) => {
if (texto.includes(kw.toLowerCase())) matchScore++;
});
return { ...diag, matchScore };
})
.filter((d) => d.matchScore > 0);

pontuados.sort((a, b) => b.matchScore - a.matchScore);

// Dedup
const prefixosIgnorar = ["ризик", "готовність до", "синдром", "схильність до", "схильність до", "ризик"];
const temasUsados = new Set();
const topDiversos = [];

function extrairTema(titulo) {
let t = titulo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
for (const p of prefixosIgnorar) {
if (t.startsWith(p)) { t = t.slice(p.length).trim(); break; }
}
const palavras = t.split(/\s+/).filter(w => w.length > 3 && !["para", "com", "sem", "como", "dos", "das", "que", "não", "nao", "melhorada", "melhorado", "prejudicada", "prejudicado", "adulto", "criança", "neonatal", "idoso", "lactente", "feminino", "masculino"].includes(w));
return palavras.slice(0, 4).join(" ");
}

for (const d of pontuados) {
const tema = extrairTema(d.diagnostico);
if (!temasUsados.has(tema) && !temasUsados.has(d.codigo)) {
temasUsados.add(tema);
temasUsados.add(d.codigo);
topDiversos.push(d);
}
if (topDiversos.length >= 6) break;
}

if (topDiversos.length > 0) {
lista.innerHTML = "";
topDiversos.forEach((d) => {
lista.innerHTML += `
<li class="nanda-item flex items-start gap-3">
<span class="bg-blue-100 text-blue-800 text-[10px] font-black px-2 py-1 rounded shadow-sm mt-0.5">${d.codigo}</span>
<div>
<h5 class="text-[13px] font-bold text-slate-800 leading-tight mb-1">${d.diagnostico}</h5>
<p class="text-[11px] text-slate-500 leading-snug m-0">${d.definicao}</p>
</div>
</li>
`;
});
} else {
lista.innerHTML = '<li class="text-xs text-slate-500 text-center py-4">Немає первинних критичних діагнозів, пов’язаних із поточним вибором.</li>';
}
} catch (e) {
lista.innerHTML = '<li class="text-xs text-red-500 text-center py-4">База даних NANDA тимчасово недоступна.</li>';
}
}

