function gerarPDF() {
if (typeof window.jspdf === "undefined") {
const btn = document.getElementById("btnGerarPDF");
const origText = btn.innerHTML;
btn.innerHTML = "Завантаження генератора...";
btn.style.opacity = "0.7"; btn.style.pointerEvents = "none";
const s1 = document.createElement("script");
s1.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
document.body.appendChild(s1);
s1.onload = () => {
const s2 = document.createElement("script");
s2.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js";
document.body.appendChild(s2);
s2.onload = () => {
btn.innerHTML = origText;
btn.style.opacity = "1"; btn.style.pointerEvents = "auto";
executarPDF();
};
};
return;
}
executarPDF();
}

function executarPDF() {
const { jsPDF } = window.jspdf;
const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
const data = getDadosImpressao();

const navy = [26, 62, 116];
const slateLight = [241, 245, 249];
const W = 210,
marginL = 18,
marginR = 18,
usable = W - marginL - marginR;

// Cabeçalho
doc.setFillColor(...navy);
doc.rect(0, 0, W, 32, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(14);
doc.text("Шкала Тінетті (POMA)", marginL, 13);
doc.setFontSize(9);
doc.setFont("helvetica", "normal");
doc.text("Оцінка ходи та рівноваги", marginL, 20);
doc.text("Дата: " + data.data, W - marginR, 20, { align: "right" });

let y = 42;

// Identificação
if (data.nome || data.idade || data.setor) {
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text("ІДЕНТИФІКАЦІЯ ПАЦІЄНТА", marginL + 4, y + 5.5);
y += 12;

if (data.nome) {
doc.text("Nome:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.nome, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.idade) {
doc.text("Idade:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.idade, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.setor) {
doc.text("Setor/Leito:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.setor, marginL + 25, y);
y += 6;
}
y += 4;
}

// Pontuação Big
doc.setFillColor(...navy);
doc.roundedRect(marginL, y, usable, 22, 3, 3, "F");
doc.setTextColor(147, 197, 253);
doc.setFont("helvetica", "bold");
doc.setFontSize(8);
doc.text(`ЧАС ОЦІНКИ: ${data.tempo}`, W / 2, y + 6, { align: "center" });
doc.setTextColor(255, 255, 255);
doc.setFontSize(26);
doc.text(String(data.soma) + " / 28", W / 2, y + 17, { align: "center" });
y += 28;

// Status Pill
let pillColor = [22, 163, 74]; // Verde
if (data.soma <= 18) pillColor = [225, 29, 72]; // Vermelho
else if (data.soma <= 23) pillColor = [234, 179, 8]; // Amarelo

doc.setFillColor(...pillColor);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text(data.classe.toUpperCase(), W / 2, y + 5.5, { align: "center" });
y += 16;

// Tabela AutoTable
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.text("ЗВЕДЕННЯ КЛІНІЧНОЇ ОЦІНКИ", marginL + 4, y + 5.5);
y += 11;

const bodyData = data.dominios.map((d) => {
return [d.nome.replace(/^\d+\.\s*/, ""), d.obtido, d.max, Math.round((d.obtido / d.max) * 100) + "%"];
});

doc.autoTable({
startY: y,
margin: { left: marginL, right: marginR },
head: [["Оцінене завдання", "Obtido", "Máx", "%"]],
body: bodyData,
foot: [["TOTAL TINETTI", data.soma, 28, Math.round((data.soma / 28) * 100) + "%"]],
styles: { fontSize: 8.5, cellPadding: 2, lineColor: [226, 232, 240], lineWidth: 0.3 },
headStyles: { fillColor: navy, textColor: 255, fontStyle: "bold" },
footStyles: { fillColor: [239, 246, 255], textColor: navy, fontStyle: "bold" },
columnStyles: { 0: { cellWidth: 100 }, 1: { halign: "center", cellWidth: 15 }, 2: { halign: "center" }, 3: { halign: "center" } },
alternateRowStyles: { fillColor: [248, 250, 252] },
});

// Rodapé
const pageCount = doc.internal.getNumberOfPages();
for(let i = 1; i <= pageCount; i++) {
doc.setPage(i);
let py = 280;
doc.setDrawColor(...slateLight);
doc.setLineWidth(0.3);
doc.line(marginL, py, W - marginR, py);
doc.setTextColor(148, 163, 184);
doc.setFontSize(7.5);
doc.setFont("helvetica", "normal");
doc.text("TINETTI, M. E. Journal of the American Geriatrics Society (1986).", marginL, py + 5);
doc.text("www.calculadorasdeenfermagem.com.br", W - marginR, py + 5, { align: "right" });
}

const nomeArquivo = data.nome ? `звіт-тінетті-${data.nome.replace(/\s+/g, "-").toLowerCase()}.pdf` : "laudo-tinetti.pdf";
doc.save(nomeArquivo);
}

